handle_menu_selection() {
    local selection="$1"
    
    case "$selection" in
        1) print_system_info ;;
        2) monitor_cpu ;;
        3) monitor_memory ;;
        4) monitor_disk ;;
        5) monitor_network ;;
        6) perform_health_check ;;
        7) analyze_system_performance ;;
        8) generate_performance_report ;;
        9) get_top_cpu_processes 10 ;;
        10) get_top_memory_processes 10 ;;
        11) list_processes ;;
        12) 
            read -p "Enter process name to find: " proc_name
            find_process_by_name "$proc_name"
            ;;
        13)
            read -p "Enter PID: " pid
            get_process_info "$pid"
            ;;
        14)
            read -p "Enter PID to monitor: " pid
            monitor_process "$pid"
            ;;
        15)
            read -p "Enter PID to kill: " pid
            kill_process_gracefully "$pid"
            ;;
        16) list_services ;;
        17)
            read -p "Enter service name: " service
            check_service_status "$service" && echo "Service is running" || echo "Service is not running"
            ;;
        18)
            read -p "Enter service name to start: " service
            start_service "$service"
            ;;
        19)
            read -p "Enter service name to stop: " service
            stop_service "$service"
            ;;
        20)
            read -p "Enter service name to restart: " service
            restart_service "$service"
            ;;
        21) list_users ;;
        22)
            read -p "Enter username: " username
            get_user_info "$username"
            ;;
        23)
            read -p "Enter username to create: " username
            read -p "Enter home directory (default /home/$username): " home_dir
            create_user "$username" "${home_dir:-/home/$username}"
            ;;
        24)
            read -p "Enter username to delete: " username
            read -p "Remove home directory? (y/n): " remove_home
            delete_user "$username" "$([[ $remove_home == 'y' ]] && echo 'true' || echo 'false')"
            ;;
        25)
            read -p "Enter username: " username
            read -p "Enter group name: " group
            add_user_to_group "$username" "$group"
            ;;
        26) list_failed_logins ;;
        27) find_suid_binaries ;;
        28) find_world_writable_files / ;;
        29) audit_file_permissions ;;
        30) list_open_ports ;;
        31)
            read -p "Enter starting path (default .): " path
            read -p "Enter minimum size (default 100M): " size
            find_large_files "${path:-.}" "${size:-100M}"
            ;;
        32)
            read -p "Enter starting path (default .): " path
            find_duplicate_files "${path:-.}"
            ;;
        33)
            read -p "Enter directory path (default .): " path
            analyze_directory_size "${path:-.}"
            ;;
        34) monitor_disk ;;
        35) list_backups ;;
        36)
            read -p "Enter path to backup: " path
            read -p "Enter backup name (optional): " name
            create_backup "$path" "$name"
            ;;
        37)
            read -p "Enter backup file path: " backup_file
            verify_backup "$backup_file"
            ;;
        38)
            read -p "Enter retention days (default 30): " days
            delete_old_backups "${days:-30}"
            ;;
        39) clean_temp_files ;;
        40) clear_log_files ;;
        41) clean_package_cache ;;
        42) remove_unused_packages ;;
        43) generate_system_report ;;
        0)
            log_info "Exiting"
            exit 0
            ;;
        *)
            print_error "Invalid selection"
            ;;
    esac
    
    read -p "Press Enter to continue..."
}

main_interactive() {
    while true; do
        show_menu
        read -p "Select option: " selection
        handle_menu_selection "$selection"
    done
}

