show_help() {
    cat << EOF
System Administration Toolkit v$SCRIPT_VERSION

USAGE: $SCRIPT_NAME [COMMAND] [OPTIONS]

COMMANDS:
    system-info             Show system information
    monitor-cpu             Monitor CPU usage
    monitor-memory          Monitor memory usage
    monitor-disk            Monitor disk usage
    monitor-network         Monitor network interfaces
    health-check            Perform system health check
    analyze-performance     Analyze system performance
    
    list-processes          List all processes
    find-process NAME       Find process by name
    get-process-info PID    Get information about a process
    kill-process PID        Gracefully terminate a process
    
    list-services           List all services
    service-status SERVICE  Check service status
    start-service SERVICE   Start a service
    stop-service SERVICE    Stop a service
    restart-service SERVICE Restart a service
    
    list-users              List all users
    user-info USERNAME      Get user information
    create-user USERNAME    Create a new user
    delete-user USERNAME    Delete a user
    
    check-ports             List listening ports
    find-large-files PATH   Find large files in directory
    disk-usage DIRECTORY    Analyze directory disk usage
    
    create-backup PATH      Create backup of path
    list-backups            List existing backups
    verify-backup FILE      Verify backup integrity
    
    system-report           Generate comprehensive system report
    
    help                    Show this help message
    version                 Show version information

EXAMPLES:
    $SCRIPT_NAME system-info
    $SCRIPT_NAME monitor-cpu
    $SCRIPT_NAME find-process sshd
    $SCRIPT_NAME create-backup /home/user
    
OPTIONS:
    --debug                 Enable debug mode
    --verbose               Enable verbose output
    --dry-run               Show what would be done (no changes)

For interactive menu, run without arguments: $SCRIPT_NAME

EOF
}

show_version() {
    echo "$SCRIPT_NAME version $SCRIPT_VERSION"
}

