# ============================================================================
# EXTENDED SECURITY & COMPLIANCE AUDITING
# ============================================================================

# Comprehensive security baseline check
audit_system_security_baseline() {
    local audit_file="$DATA_DIR/security_audit_$(date +%Y%m%d_%H%M%S).txt"
    
    {
        echo "Security Audit Report - $(date)"
        echo "==========================================="
        echo ""
        
        # Check file permissions on critical files
        echo "Critical File Permissions:"
        check_file_permissions /etc/passwd
        check_file_permissions /etc/shadow
        check_file_permissions /etc/sudoers
        echo ""
        
        # Check for weak permissions
        echo "Checking for insecure permissions..."
        find /etc -type f -perm -077 2>/dev/null | head -10
        echo ""
        
        # SSH configuration audit
        echo "SSH Configuration Audit:"
        if [[ -f /etc/ssh/sshd_config ]]; then
            grep -E "^PermitRootLogin|^PasswordAuthentication|^PubkeyAuthentication|^X11Forwarding" /etc/ssh/sshd_config
        fi
        echo ""
        
        # User account audit
        echo "User Account Audit:"
        awk -F: '$3 >= 1000 {print "User: " $1 ", UID: " $3}' /etc/passwd
        echo ""
        
        # Check for empty password fields
        echo "Checking for empty password fields..."
        awk -F: '($2 == "" || $2 == "!" || $2 == "*") {print $1 ": " $2}' /etc/shadow 2>/dev/null
        echo ""
        
        # Sudo configuration
        echo "Sudo Configuration:"
        visudo -c -f /etc/sudoers 2>&1 | grep -i "ok\|error"
        echo ""
        
        # Check for world-readable sensitive files
        echo "World-readable Sensitive Files:"
        find /etc -type f -perm -044 2>/dev/null | head -10
        
    } | tee "$audit_file"
    
    log_info "Security audit saved to: $audit_file"
}

# System compliance check against CIS benchmarks
check_cis_compliance() {
    local report="$DATA_DIR/cis_compliance_$(date +%Y%m%d_%H%M%S).txt"
    
    {
        echo "CIS Benchmark Compliance Report"
        echo "Generated: $(date)"
        echo "============================================"
        echo ""
        
        # 1. Filesystem configuration
        echo "1. FILESYSTEM CONFIGURATION"
        echo "---"
        echo "1.1 Disable unused filesystems:"
        lsmod | grep "cramfs\|freevxfs\|hfs\|hfsplus\|jffs2\|ubifs\|vfat"
        echo ""
        
        # 2. Configure software updates
        echo "2. SOFTWARE UPDATES"
        echo "---"
        if command -v apt-get &>/dev/null; then
            apt update >/dev/null 2>&1
            apt list --upgradable 2>/dev/null | head -5
        fi
        echo ""
        
        # 3. Filesystem integrity monitoring
        echo "3. FILESYSTEM INTEGRITY"
        echo "---"
        command -v aide >/dev/null 2>&1 && echo "AIDE installed" || echo "AIDE not installed"
        command -v tripwire >/dev/null 2>&1 && echo "Tripwire installed" || echo "Tripwire not installed"
        echo ""
        
        # 4. Secure boot configuration
        echo "4. SECURE BOOT"
        echo "---"
        [[ -d /sys/firmware/efi ]] && echo "UEFI boot detected" || echo "BIOS boot detected"
        echo ""
        
        # 5. Configure SELinux or AppArmor
        echo "5. MANDATORY ACCESS CONTROL"
        echo "---"
        getenforce 2>/dev/null || echo "SELinux not available"
        aa-status 2>/dev/null || echo "AppArmor not available"
        
    } | tee "$report"
}

# Advanced privilege escalation detection
detect_privilege_escalation_attempts() {
    local log_file="${1:-/var/log/auth.log}"
    local threshold="${2:-5}"
    
    if [[ ! -f "$log_file" ]]; then
        log_error "Log file not found: $log_file"
        return 1
    fi
    
    echo "Potential Privilege Escalation Attempts (last 24 hours):"
    echo "========================================================="
    
    # Check for sudo failures
    grep "sudo.*COMMAND" "$log_file" | tail -100 | while read line; do
        if echo "$line" | grep -q "user NOT in sudoers\|Authentication failure"; then
            echo "$line"
        fi
    done
    
    # Check for su attempts
    grep "su\[" "$log_file" | tail -50 | grep -i "failed\|invalid"
}

# Rootkit and malware detection scan
scan_for_rootkits() {
    local scan_dir="${1:-/}"
    
    print_header "ROOTKIT & MALWARE SCAN"
    
    # Check for hidden processes
    echo "Checking for hidden processes..."
    ps aux > /tmp/ps_aux.txt
    
    # Look for suspicious process patterns
    grep -E "bash|nc|ncat|nc.exe|nmap" /tmp/ps_aux.txt | grep -v grep
    
    # Check for suspicious files
    echo "Checking for suspicious file patterns..."
    find "$scan_dir" -name "..*" -type f 2>/dev/null | head -10
    
    # Check for unusual socket connections
    echo "Checking for unusual network connections..."
    if command -v lsof &>/dev/null; then
        lsof -i -P -n 2>/dev/null | grep -i "established\|listen" | head -20
    fi
    
    # Check startup locations for suspicious files
    for startup_dir in /etc/init.d /etc/rc.d /lib/systemd/system; do
        if [[ -d "$startup_dir" ]]; then
            echo "Checking $startup_dir..."
            find "$startup_dir" -type f -newer /var/log/auth.log 2>/dev/null
        fi
    done
    
    rm -f /tmp/ps_aux.txt
}

