# Comprehensive network configuration audit
audit_network_configuration() {
    local report="$DATA_DIR/network_audit_$(date +%Y%m%d_%H%M%S).txt"
    
    {
        echo "Network Configuration Audit"
        echo "Generated: $(date)"
        echo "=================================="
        echo ""
        
        echo "Network Interfaces:"
        ip addr show 2>/dev/null || ifconfig
        echo ""
        
        echo "Routing Table:"
        ip route show 2>/dev/null || route -n
        echo ""
        
        echo "DNS Configuration:"
        cat /etc/resolv.conf 2>/dev/null | grep -v "^#"
        echo ""
        
        echo "Listening Ports:"
        ss -tlnp 2>/dev/null || netstat -tlnp
        echo ""
        
        echo "Established Connections:"
        ss -tnp 2>/dev/null | grep ESTAB | head -20
        echo ""
        
        echo "IP Forwarding Status:"
        cat /proc/sys/net/ipv4/ip_forward 2>/dev/null
        echo ""
        
        echo "Firewall Status (iptables):"
        iptables -L -n 2>/dev/null | head -20
        
    } | tee "$report"
}

# TCP/UDP port scanner
scan_ports() {
    local host="$1"
    local port_range="${2:-1-1024}"
    local timeout="${3:-1}"
    
    if ! validate_ip "$host" && ! ping -c 1 -W 2 "$host" &>/dev/null; then
        log_error "Cannot reach host: $host"
        return 1
    fi
    
    echo "Scanning ports on $host..."
    
    local start_port=$(echo "$port_range" | cut -d- -f1)
    local end_port=$(echo "$port_range" | cut -d- -f2)
    
    for ((port = start_port; port <= end_port; port++)); do
        timeout "$timeout" bash -c "</dev/tcp/$host/$port" 2>/dev/null && \
            echo "Port $port: OPEN"
    done
}

# Network traffic analysis
analyze_network_traffic() {
    local interface="${1:-eth0}"
    local packet_count="${2:-100}"
    
    if ! command -v tcpdump &>/dev/null; then
        log_error "tcpdump not installed"
        return 1
    fi
    
    require_root
    
    echo "Analyzing traffic on $interface (capturing $packet_count packets)..."
    tcpdump -i "$interface" -c "$packet_count" -nn -q 2>/dev/null | \
        awk '
        /IP / {
            src = $2
            dst = $4
            gsub(/\.[0-9]*:/, "", src)
            gsub(/\.[0-9]*:/, "", dst)
            ips[src]++
            ips[dst]++
        }
        END {
            for (ip in ips) {
                print ip ": " ips[ip]
            }
        }
        ' | sort -t: -k2 -rn | head -20
}

# Bandwidth monitoring
monitor_bandwidth() {
    local interface="${1:-eth0}"
    local interval="${2:-5}"
    local iterations="${3:-10}"
    
    if [[ ! -d /sys/class/net/$interface ]]; then
        log_error "Interface not found: $interface"
        return 1
    fi
    
    echo "Monitoring bandwidth on $interface (interval: ${interval}s, iterations: $iterations)"
    echo "========================================================================"
    
    local rx_prev=$(cat /sys/class/net/$interface/statistics/rx_bytes 2>/dev/null)
    local tx_prev=$(cat /sys/class/net/$interface/statistics/tx_bytes 2>/dev/null)
    local timestamp=$(date +%s)
    
    for ((i = 0; i < iterations; i++)); do
        sleep "$interval"
        
        local rx_curr=$(cat /sys/class/net/$interface/statistics/rx_bytes 2>/dev/null)
        local tx_curr=$(cat /sys/class/net/$interface/statistics/tx_bytes 2>/dev/null)
        local timestamp_new=$(date +%s)
        
        local time_diff=$((timestamp_new - timestamp))
        [[ $time_diff -eq 0 ]] && time_diff=1
        
        local rx_rate=$(( (rx_curr - rx_prev) / time_diff ))
        local tx_rate=$(( (tx_curr - tx_prev) / time_diff ))
        
        echo "$(date +%H:%M:%S) - RX: $(human_readable_size $rx_rate)/s | TX: $(human_readable_size $tx_rate)/s"
        
        rx_prev=$rx_curr
        tx_prev=$tx_curr
        timestamp=$timestamp_new
    done
}

# DNS resolution testing and diagnostics
test_dns_resolution() {
    local domain="${1:-example.com}"
    
    echo "DNS Resolution Test for: $domain"
    echo "========================================"
    echo ""
    
    # Test with default resolver
    echo "Using default resolver:"
    nslookup "$domain" 2>/dev/null | grep -E "Name:|Address:"
    echo ""
    
    # Test with Google DNS
    echo "Using Google DNS (8.8.8.8):"
    nslookup "$domain" 8.8.8.8 2>/dev/null | grep -E "Name:|Address:"
    echo ""
    
    # Test reverse DNS
    echo "Reverse DNS lookup:"
    local ip=$(dig +short "$domain" | head -1)
    if [[ -n "$ip" ]]; then
        dig +short -x "$ip"
    fi
    echo ""
    
    # Trace DNS lookup
    echo "DNS Query Trace:"
    dig +trace "$domain" 2>/dev/null | grep -E "^$domain|^\;" | head -10
}

