# LVM (Logical Volume Manager) diagnostic tool
analyze_lvm_configuration() {
    if ! command -v lvs &>/dev/null; then
        log_error "LVM tools not installed"
        return 1
    fi
    
    require_root
    
    print_header "LVM CONFIGURATION ANALYSIS"
    
    echo "Physical Volumes:"
    pvs 2>/dev/null || echo "No PVs found"
    echo ""
    
    echo "Volume Groups:"
    vgs 2>/dev/null || echo "No VGs found"
    echo ""
    
    echo "Logical Volumes:"
    lvs 2>/dev/null || echo "No LVs found"
    echo ""
    
    echo "Detailed Volume Information:"
    lvdisplay 2>/dev/null | head -50
}

# RAID array health monitoring
check_raid_status() {
    if [[ ! -f /proc/mdstat ]]; then
        log_warn "No RAID arrays detected"
        return 0
    fi
    
    echo "RAID Array Status:"
    echo "==================="
    cat /proc/mdstat
    echo ""
    
    # Check for degraded arrays
    if grep -q "_" /proc/mdstat; then
        print_warning "Degraded RAID arrays detected"
    else
        print_success "All RAID arrays healthy"
    fi
}

# Filesystem fragmentation analysis
analyze_fragmentation() {
    local filesystem="${1:-.}"
    
    if ! command -v filefrag &>/dev/null; then
        log_error "filefrag not installed"
        return 1
    fi
    
    echo "Analyzing fragmentation for: $filesystem"
    echo "=========================================="
    
    filefrag -e "$filesystem" 2>/dev/null | grep -E "Extents|Fragmented" | head -20
}

# Extended filesystem consistency check
check_filesystem_consistency() {
    local device="$1"
    
    require_root
    
    if [[ -z "$device" ]]; then
        log_error "Device path required"
        return 1
    fi
    
    # Unmount device first
    local mount_point=$(mount | grep "$device" | awk '{print $3}')
    if [[ -n "$mount_point" ]]; then
        log_warn "Device is mounted at $mount_point"
        log_info "Attempting to unmount for consistency check..."
        umount "$mount_point" 2>/dev/null || log_error "Could not unmount device"
        return 1
    fi
    
    # Run filesystem check
    echo "Running filesystem consistency check..."
    fsck -n "$device" 2>&1 | tail -20
}

# Disk quota management
setup_disk_quotas() {
    local filesystem="$1"
    local user="$2"
    local soft_limit="$3"
    local hard_limit="$4"
    
    require_root
    
    if ! command -v setquota &>/dev/null; then
        log_error "Quota tools not installed"
        return 1
    fi
    
    log_info "Setting quota for $user on $filesystem"
    setquota -u "$user" "$soft_limit" "$hard_limit" 0 0 "$filesystem"
}

# ============================================================================
# ADVANCED PERFORMANCE TUNING
# ============================================================================

# System memory optimization recommendations
optimize_memory_usage() {
    print_header "MEMORY OPTIMIZATION RECOMMENDATIONS"
    
    local mem_usage=$(get_memory_usage)
    
    if (( mem_usage > 80 )); then
        echo "High Memory Usage Detected ($mem_usage%)"
        echo ""
        echo "Recommendations:"
        echo "1. Increase swap space (if available)"
        echo "2. Kill unnecessary processes:"
        get_top_memory_processes 5 | awk '{print "   - " $1 " (" $11 "): " $4 "%"}'
        echo "3. Check for memory leaks"
        echo "4. Consider increasing RAM"
    else
        echo "Memory usage is acceptable ($mem_usage%)"
    fi
}

# CPU performance tuning
analyze_cpu_performance() {
    print_header "CPU PERFORMANCE ANALYSIS"
    
    echo "CPU Frequency Information:"
    if [[ -f /proc/cpuinfo ]]; then
        grep "cpu MHz" /proc/cpuinfo | head -5
    fi
    echo ""
    
    echo "CPU Governor:"
    if [[ -d /sys/devices/system/cpu/cpu0/cpufreq ]]; then
        cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo "Not available"
    fi
    echo ""
    
    echo "Context Switches:"
    grep "ctxt" /proc/stat
    echo ""
    
    echo "Process Queue Depth:"
    uptime | awk -F'load average:' '{print $2}'
}

# I/O performance monitoring
monitor_io_performance() {
    if ! command -v iostat &>/dev/null; then
        log_error "iostat not installed (install sysstat package)"
        return 1
    fi
    
    require_root
    
    print_header "I/O PERFORMANCE MONITORING"
    
    echo "Current I/O Statistics:"
    iostat -x 1 2 | tail -20
}

# System call tracing for performance analysis
trace_system_calls() {
    local pid="$1"
    local duration="${2:-10}"
    
    if ! command -v strace &>/dev/null; then
        log_error "strace not installed"
        return 1
    fi
    
    require_root
    
    echo "Tracing system calls for PID $pid (${duration}s)..."
    strace -p "$pid" -c -e trace=all 2>&1 &
    local strace_pid=$!
    
    sleep "$duration"
    kill $strace_pid 2>/dev/null
    wait $strace_pid 2>/dev/null
}

