# Real-time system metrics dashboard
display_metrics_dashboard() {
    local refresh_interval="${1:-5}"
    
    while true; do
        clear
        
        echo "╔════════════════════════════════════════════════════════════════════╗"
        echo "║         SYSTEM METRICS DASHBOARD - $(date +'%Y-%m-%d %H:%M:%S')             ║"
        echo "╚════════════════════════════════════════════════════════════════════╝"
        echo ""
        
        # CPU
        local cpu_usage=$(get_cpu_usage)
        printf "CPU Usage:      "
        draw_progress_bar "$cpu_usage" 100
        echo ""
        
        # Memory
        local mem_usage=$(get_memory_usage)
        printf "Memory Usage:   "
        draw_progress_bar "$mem_usage" 100
        echo ""
        
        # Disk
        local disk_usage=$(df / 2>/dev/null | tail -1 | awk '{print $5}' | tr -d '%')
        printf "Disk Usage:     "
        draw_progress_bar "$disk_usage" 100
        echo ""
        
        # Network connections
        local conn_count=$(ss -tn 2>/dev/null | wc -l)
        echo "Active Connections: $conn_count"
        echo ""
        
        # Top processes
        echo "Top 5 Processes (CPU):"
        get_top_cpu_processes 5 | awk '{printf "  %-8s %-20s %6s%%\n", $1, substr($11,1,20), $3}'
        echo ""
        
        echo "Last update: $(date +'%H:%M:%S')"
        echo "Press Ctrl+C to exit (refreshing in ${refresh_interval}s)"
        
        sleep "$refresh_interval"
    done
}

# Helper function to draw progress bar
draw_progress_bar() {
    local current="$1"
    local total="$2"
    local width=30
    
    local percent=$((current * 100 / total))
    local filled=$((percent * width / 100))
    
    printf "["
    for ((i = 0; i < filled; i++)); do printf "="; done
    for ((i = filled; i < width; i++)); do printf " "; done
    printf "] %d%%\n" "$percent"
}

# Alert system based on thresholds
configure_alerts() {
    local cpu_threshold="${1:-90}"
    local mem_threshold="${2:-90}"
    local disk_threshold="${3:-90}"
    
    log_info "Configuring alerts..."
    log_info "CPU threshold: $cpu_threshold%"
    log_info "Memory threshold: $mem_threshold%"
    log_info "Disk threshold: $disk_threshold%"
}

# Email alert function
send_alert_email() {
    local recipient="$1"
    local subject="$2"
    local message="$3"
    
    if ! command -v mail &>/dev/null && ! command -v sendmail &>/dev/null; then
        log_warn "No mail utility available"
        return 1
    fi
    
    echo "$message" | mail -s "$subject" "$recipient" 2>/dev/null && \
        log_info "Alert email sent to $recipient" || \
        log_error "Failed to send alert email"
}

