# Implement automated data archival policy
archive_old_files() {
    local source_dir="$1"
    local archive_dir="${2:-.}"
    local days="${3:-30}"
    
    if [[ ! -d "$source_dir" ]]; then
        log_error "Source directory not found: $source_dir"
        return 1
    fi
    
    local archive_file="${archive_dir}/archive_$(date +%Y%m%d_%H%M%S).tar.gz"
    
    log_info "Archiving files older than $days days..."
    
    find "$source_dir" -type f -mtime +$days -print0 | xargs -0 tar -czf "$archive_file" 2>/dev/null
    
    if [[ -f "$archive_file" ]]; then
        log_info "Archive created: $archive_file"
        echo "$archive_file"
        return 0
    else
        log_error "Failed to create archive"
        return 1
    fi
}

# Selective file compression
compress_files() {
    local directory="$1"
    local min_age="${2:-7}"
    local min_size="${3:-1M}"
    
    echo "Compressing files older than $min_age days and larger than $min_size..."
    
    find "$directory" -type f -mtime +$min_age -size +$min_size ! -name "*.gz" ! -name "*.bz2" \
        -exec gzip {} \; 2>/dev/null && \
        echo "Compression complete" || \
        echo "Some files could not be compressed"
}

# Backup retention policy management
enforce_backup_retention() {
    local backup_dir="$1"
    local retention_days="${2:-30}"
    local min_backups="${3:-3}"
    
    local backup_count=$(find "$backup_dir" -name "*.tar.gz" -type f | wc -l)
    
    if (( backup_count > min_backups )); then
        echo "Enforcing retention policy: keeping last $min_backups backups"
        find "$backup_dir" -name "*.tar.gz" -type f -mtime +$retention_days -delete
        log_info "Backup retention policy enforced"
    fi
}

