# Generate comprehensive system documentation
generate_system_documentation() {
    local doc_file="$DATA_DIR/system_documentation_$(date +%Y%m%d_%H%M%S).md"
    
    {
        echo "# System Documentation Report"
        echo "Generated: $(date)"
        echo ""
        
        echo "## System Information"
        echo ""
        echo "\`\`\`"
        gather_system_info
        for key in "${!SYSTEM_INFO[@]}"; do
            echo "$key: ${SYSTEM_INFO[$key]}"
        done
        echo "\`\`\`"
        echo ""
        
        echo "## Network Configuration"
        echo ""
        echo "\`\`\`"
        ip addr show 2>/dev/null || ifconfig
        echo "\`\`\`"
        echo ""
        
        echo "## Installed Services"
        echo ""
        if command -v systemctl &>/dev/null; then
            echo "\`\`\`"
            systemctl list-units --type=service --state=running | grep ".service" | awk '{print $1}'
            echo "\`\`\`"
        fi
        echo ""
        
        echo "## Storage Configuration"
        echo ""
        echo "\`\`\`"
        df -h
        echo "\`\`\`"
        
    } > "$doc_file"
    
    log_info "Documentation generated: $doc_file"
    echo "$doc_file"
}

# Interactive troubleshooting guide
start_troubleshooting_wizard() {
    print_header "SYSTEM TROUBLESHOOTING WIZARD"
    
    echo ""
    echo "What problem are you experiencing?"
    echo ""
    echo "1. High CPU usage"
    echo "2. High memory usage"
    echo "3. Disk full/space issues"
    echo "4. Network connectivity problems"
    echo "5. Service not running"
    echo "6. Slow system performance"
    echo "7. Login/authentication issues"
    echo "0. Cancel"
    echo ""
    
    read -p "Select issue (0-7): " issue
    
    case "$issue" in
        1)
            echo "High CPU Usage Diagnosis:"
            monitor_cpu
            echo ""
            echo "Recommendations:"
            echo "- Check top CPU consuming processes above"
            echo "- Kill unnecessary processes: kill_process PID"
            echo "- Review application logs for errors"
            ;;
        2)
            echo "High Memory Usage Diagnosis:"
            monitor_memory
            echo ""
            echo "Recommendations:"
            echo "- Check top memory consuming processes above"
            echo "- Increase swap space if available"
            echo "- Reduce cache usage: sync && echo 3 > /proc/sys/vm/drop_caches"
            ;;
        3)
            echo "Disk Space Diagnosis:"
            monitor_disk
            echo ""
            echo "Recommendations:"
            echo "- Find large files: find_large_files /"
            echo "- Remove old logs: clean_temp_files"
            echo "- Compress old files: compress_files /var/log"
            ;;
        4)
            echo "Network Connectivity Diagnosis:"
            monitor_network
            echo ""
            echo "Recommendations:"
            echo "- Check interface status: get_interface_stats eth0"
            echo "- Test DNS: test_dns_resolution"
            echo "- Check firewall rules: iptables -L -n"
            ;;
        5)
            read -p "Enter service name: " service
            echo "Service Status Diagnosis for: $service"
            systemctl status "$service" 2>/dev/null || service "$service" status
            echo ""
            echo "Recommendations:"
            echo "- Start service: start_service $service"
            echo "- View service logs: journalctl -u $service -n 50"
            ;;
        6)
            echo "System Performance Diagnosis:"
            analyze_system_performance
            ;;
        7)
            echo "Authentication Issues Diagnosis:"
            echo "Recent failed login attempts:"
            list_failed_logins | tail -5
            ;;
        0)
            echo "Canceling troubleshooting wizard"
            ;;
        *)
            echo "Invalid selection"
            ;;
    esac
}

