# Save current system configuration for comparison
save_system_baseline() {
    local baseline_file="$DATA_DIR/system_baseline_$(date +%Y%m%d_%H%M%S).tar.gz"
    
    echo "Saving system baseline..."
    
    tar -czf "$baseline_file" \
        /etc/hostname \
        /etc/network \
        /etc/ssh \
        /etc/sudoers \
        /etc/fstab \
        /etc/crontab \
        /etc/passwd \
        /etc/group \
        2>/dev/null
    
    log_info "System baseline saved: $baseline_file"
    echo "$baseline_file"
}

# Compare current configuration with saved baseline
compare_with_baseline() {
    local baseline_file="$1"
    
    if [[ ! -f "$baseline_file" ]]; then
        log_error "Baseline file not found: $baseline_file"
        return 1
    fi
    
    local extract_dir="$TEMP_DIR/baseline_extract"
    mkdir -p "$extract_dir"
    
    echo "Extracting baseline..."
    tar -xzf "$baseline_file" -C "$extract_dir" 2>/dev/null
    
    echo "Comparing configurations..."
    diff -r "$extract_dir/etc" /etc 2>/dev/null | head -50
}

