# Extended validation functions
validate_hostname() {
    local hostname="$1"
    local regex='^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\-]*[a-zA-Z0-9])\.)*([A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\-]*[A-Za-z0-9])$'
    [[ $hostname =~ $regex ]] && return 0 || return 1
}

validate_mac_address() {
    local mac="$1"
    local regex='^([0-9A-Fa-f]{2}[:]){5}([0-9A-Fa-f]{2})$'
    [[ $mac =~ $regex ]] && return 0 || return 1
}

validate_url() {
    local url="$1"
    local regex='https?://[-A-Za-z0-9\+&@#/%?=~_|!:,.;]*[-A-Za-z0-9\+&@#/%=~_|]'
    [[ $url =~ $regex ]] && return 0 || return 1
}

# Text formatting utilities
center_text() {
    local text="$1"
    local width="${2:-80}"
    local padding=$(( (width - ${#text}) / 2 ))
    printf "%*s%s\n" $padding "" "$text"
}

wrap_text() {
    local text="$1"
    local width="${2:-80}"
    echo "$text" | fold -w "$width" -s
}

indent_text() {
    local indent="$1"
    shift
    while IFS= read -r line; do
        echo "${indent}${line}"
    done
}

# Array utilities
array_contains() {
    local needle="$1"
    shift
    for item in "$@"; do
        [[ "$item" == "$needle" ]] && return 0
    done
    return 1
}

join_array() {
    local separator="$1"
    shift
    local first=true
    for item in "$@"; do
        if [[ "$first" == true ]]; then
            printf "%s" "$item"
            first=false
        else
            printf "%s%s" "$separator" "$item"
        fi
    done
    echo
}

# String manipulation utilities
string_reverse() {
    local string="$1"
    echo "$string" | rev
}

string_uppercase() {
    echo "$1" | tr '[:lower:]' '[:upper:]'
}

string_lowercase() {
    echo "$1" | tr '[:upper:]' '[:lower:]'
}

# Checksum utilities
calculate_file_checksum() {
    local file="$1"
    local algorithm="${2:-sha256}"
    
    case "$algorithm" in
        md5)
            md5sum "$file" | awk '{print $1}'
            ;;
        sha1)
            sha1sum "$file" | awk '{print $1}'
            ;;
        sha256)
            sha256sum "$file" | awk '{print $1}'
            ;;
        sha512)
            sha512sum "$file" | awk '{print $1}'
            ;;
        *)
            log_error "Unknown algorithm: $algorithm"
            return 1
            ;;
    esac
}

# Date/time utilities
get_unix_timestamp() {
    date +%s
}

convert_unix_timestamp() {
    local timestamp="$1"
    date -d @"$timestamp" 2>/dev/null || date -r "$timestamp" 2>/dev/null
}

get_week_number() {
    date +%V
}

get_day_of_week() {
    date +%A
}

# Random data generation
generate_random_string() {
    local length="${1:-16}"
    openssl rand -hex $((length / 2)) 2>/dev/null || tr -dc 'A-Za-z0-9' < /dev/urandom | head -c "$length"
}

generate_random_password() {
    local length="${1:-16}"
    openssl rand -base64 $((length * 6 / 8)) 2>/dev/null | cut -c1-"$length" || tr -dc 'A-Za-z0-9!@#$%^&*' < /dev/urandom | head -c "$length"
}

# JSON parsing utilities
json_extract_field() {
    local json="$1"
    local field="$2"
    echo "$json" | grep -o "\"$field\":[^,}]*" | cut -d':' -f2 | tr -d ' "'
}

# CSV utilities
csv_to_json() {
    local csv_file="$1"
    
    awk -F, '
    NR==1 {
        for (i=1; i<=NF; i++) {
            headers[i] = $i
        }
        next
    }
    {
        printf "{"
        for (i=1; i<=NF; i++) {
            printf "\"%s\": \"%s\"", headers[i], $i
            if (i < NF) printf ", "
        }
        printf "}\n"
    }
    ' "$csv_file"
}

# Database utilities (generic SQL helpers)
execute_sql_query() {
    local db_type="$1"
    local connection="$2"
    local query="$3"
    
    case "$db_type" in
        sqlite)
            sqlite3 "$connection" "$query"
            ;;
        mysql)
            mysql -u "${connection%:*}" -p"${connection##*:}" -e "$query"
            ;;
        postgresql)
            psql "$connection" -c "$query"
            ;;
        *)
            log_error "Unsupported database type: $db_type"
            return 1
            ;;
    esac
}

# Configuration file management
parse_config_file() {
    local config_file="$1"
    
    while IFS='=' read -r key value; do
        [[ "$key" =~ ^#.*$ ]] && continue
        [[ -z "$key" ]] && continue
        key=$(echo "$key" | xargs)
        value=$(echo "$value" | xargs)
        CONFIG["$key"]="$value"
    done < "$config_file"
}

write_config_file() {
    local config_file="$1"
    
    {
        echo "# Configuration file - Generated by System Administration Toolkit"
        echo "# Generated: $(date)"
        echo ""
        for key in "${!CONFIG[@]}"; do
            echo "${key}=${CONFIG[$key]}"
        done
    } > "$config_file"
}

# Lock file management
acquire_lock() {
    local lock_file="$1"
    local timeout="${2:-30}"
    
    local elapsed=0
    while [[ -f "$lock_file" ]] && (( elapsed < timeout )); do
        sleep 1
        ((elapsed++))
    done
    
    if [[ -f "$lock_file" ]]; then
        log_error "Could not acquire lock"
        return 1
    fi
    
    echo $$ > "$lock_file"
    return 0
}

release_lock() {
    local lock_file="$1"
    rm -f "$lock_file"
}

# Comprehensive final status message
display_script_status() {
    print_header "SYSTEM ADMINISTRATION TOOLKIT STATUS"
    
