# Advanced log rotation and compression utilities
manage_system_logs() {
    local log_pattern="$1"
    local max_rotations="${2:-10}"
    local compression="${3:-true}"
    
    echo "Managing logs matching: $log_pattern"
    
    find /var/log -name "$log_pattern" -type f | while read logfile; do
        if [[ -f "$logfile" ]]; then
            local size=$(stat -f%z "$logfile" 2>/dev/null || stat -c%s "$logfile")
            
            if (( size > MAX_LOG_SIZE )); then
                local timestamp=$(date +%Y%m%d_%H%M%S)
                local rotated="${logfile}.${timestamp}"
                
                mv "$logfile" "$rotated"
                touch "$logfile"
                
                if [[ "$compression" == "true" ]]; then
                    gzip "$rotated"
                fi
                
                # Remove old rotated files
                find "${logfile}*" -mtime +30 -delete
                
                log_info "Rotated log: $logfile"
            fi
        fi
    done
}

# Process state monitoring and tracking
track_process_state() {
    local pid="$1"
    local history_file="$DATA_DIR/process_history_${pid}_$(date +%Y%m%d).txt"
    
    {
        echo "Process State History - PID: $pid"
        echo "Timestamp: $(date)"
        echo "=============================================="
        
        if [[ -f /proc/$pid/stat ]]; then
            echo "Process Status:"
            ps -p $pid -o pid,ppid,cmd,stat,etime,time
            
            echo ""
            echo "Memory Usage:"
            ps -p $pid -o pid,rss,vsz,pmem
            
            echo ""
            echo "File Descriptors:"
            ls -la /proc/$pid/fd 2>/dev/null | wc -l
            
            echo ""
            echo "Environment Variables:"
            cat /proc/$pid/environ | tr '\0' '\n' | head -10
        else
            echo "Process not found"
        fi
    } >> "$history_file"
}

# Comprehensive user activity logging
audit_user_activities() {
    local username="$1"
    local days="${2:-7}"
    
    echo "User Activity Audit for: $username (last $days days)"
    echo "========================================================="
    echo ""
    
    echo "Login History:"
    lastlog -u "$username" 2>/dev/null | head -10
    echo ""
    
    echo "Last Commands:"
    if [[ -f /home/$username/.bash_history ]]; then
        tail -20 /home/$username/.bash_history 2>/dev/null
    fi
    echo ""
    
    echo "File Access:"
    find /home/$username -type f -mtime -$days -ls 2>/dev/null | head -20
}

# Advanced system state snapshots
create_system_snapshot() {
    local snapshot_name="snapshot_$(date +%Y%m%d_%H%M%S)"
    local snapshot_dir="$DATA_DIR/$snapshot_name"
    
    mkdir -p "$snapshot_dir"
    
    # Capture various system states
    ps auxf > "$snapshot_dir/processes.txt"
    netstat -tlnp > "$snapshot_dir/network.txt" 2>/dev/null
    df -h > "$snapshot_dir/disk.txt"
    free -h > "$snapshot_dir/memory.txt"
    uptime > "$snapshot_dir/uptime.txt"
    systemctl status > "$snapshot_dir/services.txt" 2>/dev/null
    
    log_info "System snapshot created: $snapshot_dir"
    echo "$snapshot_dir"
}

# Compare system snapshots to detect changes
compare_snapshots() {
    local snapshot1="$1"
    local snapshot2="$2"
    
    if [[ ! -d "$snapshot1" ]] || [[ ! -d "$snapshot2" ]]; then
        log_error "Invalid snapshot paths"
        return 1
    fi
    
    echo "Comparison between snapshots:"
    echo "============================="
    
    diff "$snapshot1/processes.txt" "$snapshot2/processes.txt" | head -20
    echo ""
    
    diff "$snapshot1/disk.txt" "$snapshot2/disk.txt"
    echo ""
    
    diff "$snapshot1/memory.txt" "$snapshot2/memory.txt"
}

# Extended network diagnostics and troubleshooting
advanced_network_diagnostics() {
    local target_host="$1"
    
    if [[ -z "$target_host" ]]; then
        target_host="8.8.8.8"
    fi
    
    print_header "ADVANCED NETWORK DIAGNOSTICS"
    
    echo "Target: $target_host"
    echo ""
    
    # MTU testing
    echo "1. MTU Discovery:"
    ping -M do -s 1472 "$target_host" -c 1 2>/dev/null && echo "Standard MTU (1500) is OK" || echo "MTU size issue detected"
    echo ""
    
    # Traceroute analysis
    echo "2. Route Analysis:"
    if command -v traceroute &>/dev/null; then
        traceroute -m 10 "$target_host" 2>/dev/null | head -15
    else
        echo "traceroute not available"
    fi
    echo ""
    
    # TCP vs UDP latency
    echo "3. Protocol Latency:"
    echo "ICMP latency:"
    ping -c 3 -W 1 "$target_host" 2>/dev/null | grep min/avg/max
    echo ""
    
    # Connection establishment time
    echo "4. TCP Connection Time:"
    time timeout 3 bash -c "</dev/tcp/$target_host/80" 2>/dev/null
}

# Memory leak detection utilities
detect_memory_leaks() {
    local pid="$1"
    local sample_count="${2:-5}"
    local interval="${3:-10}"
    
    if [[ ! -d /proc/$pid ]]; then
        log_error "Process not found: $pid"
        return 1
    fi
    
    echo "Memory Leak Detection for PID: $pid"
    echo "====================================="
    echo ""
    
    local prev_rss=0
    
    for ((i = 0; i < sample_count; i++)); do
        local rss=$(ps -p $pid -o rss= 2>/dev/null)
        
        if [[ -z "$rss" ]]; then
            echo "Process terminated"
            break
        fi
        
        local growth=$((rss - prev_rss))
        echo "[$(date +'%H:%M:%S')] RSS: ${rss}KB, Growth: +${growth}KB"
        
        prev_rss=$rss
        sleep "$interval"
    done
}

# System load analysis and forecasting
analyze_system_load() {
    print_header "SYSTEM LOAD ANALYSIS"
    
    # Get current load averages
    local load_1=$(uptime | awk -F'load average:' '{print $2}' | awk '{print $1}' | tr -d ',')
    local load_5=$(uptime | awk -F'load average:' '{print $2}' | awk '{print $2}' | tr -d ',')
    local load_15=$(uptime | awk -F'load average:' '{print $2}' | awk '{print $3}')
    
    local cpu_count=$(nproc 2>/dev/null || sysctl -n hw.ncpu)
    
    echo "Current Load Averages:"
    printf "%-20s: %.2f\n" "1-minute" "$load_1"
    printf "%-20s: %.2f\n" "5-minute" "$load_5"
    printf "%-20s: %.2f\n" "15-minute" "$load_15"
    printf "%-20s: %d\n" "CPU Cores" "$cpu_count"
    echo ""
    
    # Analyze trend
    echo "Load Trend Analysis:"
    if (( $(echo "$load_1 > $load_5" | bc -l) )); then
        echo "Load is INCREASING"
    elif (( $(echo "$load_1 < $load_5" | bc -l) )); then
        echo "Load is DECREASING"
    else
        echo "Load is STABLE"
    fi
    echo ""
    
    # Recommendations
    echo "System Status:"
    if (( $(echo "$load_15 > $cpu_count" | bc -l) )); then
        echo "⚠ System is OVERLOADED (load > CPU count)"
    elif (( $(echo "$load_15 > ($cpu_count * 0.8)" | bc -l) )); then
        echo "⚠ System is UNDER PRESSURE"
    else
        echo "✓ System load is HEALTHY"
    fi
}

# Context switch and interrupt analysis
analyze_system_interrupts() {
    echo "System Context Switches and Interrupts:"
    echo "========================================="
    
    if [[ -f /proc/stat ]]; then
        grep "ctxt" /proc/stat
        echo ""
        
        echo "Top Interrupt Sources:"
        head -20 /proc/interrupts | tail -10
    fi
}

# File system event monitoring
monitor_filesystem_events() {
    local target_dir="$1"
    local timeout="${2:-60}"
    
    if ! command -v inotifywait &>/dev/null; then
        log_error "inotify-tools not installed"
        return 1
    fi
    
    echo "Monitoring filesystem events in: $target_dir"
    echo "Timeout: ${timeout}s"
    echo "=========================================="
    
    inotifywait -r -m -e modify,create,delete "$target_dir" --timeout "$timeout" 2>/dev/null
}

# System clock and time sync monitoring
monitor_time_synchronization() {
    echo "Time Synchronization Status:"
    echo "============================"
    
    # NTP status
    if command -v ntpq &>/dev/null; then
        echo "NTP Status:"
        ntpq -p 2>/dev/null | head -10
    elif command -v timedatectl &>/dev/null; then
        echo "Systemd-timesyncd Status:"
        timedatectl status
    fi
    
    echo ""
    echo "Current Time:"
    date
    echo ""
    
    echo "Hardware Clock:"
    hwclock --show 2>/dev/null || echo "Cannot read hardware clock"
}

# Comprehensive firewall rule analysis
analyze_firewall_rules() {
    print_header "FIREWALL RULES ANALYSIS"
    
    if command -v firewall-cmd &>/dev/null; then
        echo "Firewalld Status:"
        firewall-cmd --state
        echo ""
        
        echo "Active Zones:"
        firewall-cmd --get-active-zones
        echo ""
        
        echo "Allowed Services:"
        firewall-cmd --list-services
    elif command -v iptables &>/dev/null; then
        echo "IPTables Rules:"
        echo ""
        
        echo "Filter Table (INPUT chain):"
        iptables -L INPUT -v -n
        echo ""
        
        echo "Filter Table (OUTPUT chain):"
        iptables -L OUTPUT -v -n
    fi
}

# Connection tracking and statistics
analyze_connection_tracking() {
    echo "Connection Tracking Statistics:"
    echo "================================"
    
    if [[ -f /proc/net/nf_conntrack ]]; then
        local conn_count=$(wc -l < /proc/net/nf_conntrack)
        echo "Total Connections Tracked: $conn_count"
        echo ""
        
        echo "Top Connection Types:"
        awk '{print $3}' /proc/net/nf_conntrack | cut -d= -f2 | sort | uniq -c | sort -rn | head -10
        echo ""
        
        echo "Top Source IPs:"
        awk '{print $7}' /proc/net/nf_conntrack | cut -d= -f2 | sort | uniq -c | sort -rn | head -10
    else
        log_warn "Connection tracking not available"
    fi
}

# Traffic control (QoS) monitoring
monitor_traffic_control() {
    local interface="${1:-eth0}"
    
    if ! command -v tc &>/dev/null; then
        log_error "tc (traffic control) not installed"
        return 1
    fi
    
    echo "Traffic Control Status for $interface:"
    echo "======================================"
    
    tc qdisc show dev "$interface"
    echo ""
    
    tc class show dev "$interface"
    echo ""
    
    tc filter show dev "$interface"
}

# Extensive system backup verification
verify_backup_integrity() {
    local backup_file="$1"
    local extract_dir="$TEMP_DIR/backup_verify_$$"
    
    if [[ ! -f "$backup_file" ]]; then
        log_error "Backup file not found: $backup_file"
        return 1
    fi
    
    mkdir -p "$extract_dir"
    
    echo "Verifying backup integrity: $backup_file"
    echo "=========================================="
    echo ""
    
    # Test extraction
    if tar -tzf "$backup_file" > /dev/null 2>&1; then
        echo "✓ Backup archive integrity: OK"
    else
        echo "✗ Backup archive integrity: FAILED"
        return 1
    fi
    
    # Calculate checksums
    echo ""
    echo "Backup Checksums:"
    tar -tzf "$backup_file" | head -20
    echo ""
    
    # File count statistics
    echo "Archive Statistics:"
    echo "Total files: $(tar -tzf "$backup_file" | wc -l)"
    echo "Archive size: $(du -sh "$backup_file" | awk '{print $1}')"
    echo "Uncompressed size: $(tar -tzf "$backup_file" | wc -c | numfmt --to=iec 2>/dev/null || du -sh "$TEMP_DIR")"
    
    rm -rf "$extract_dir"
}

# Disaster recovery planning and testing
test_disaster_recovery() {
    print_header "DISASTER RECOVERY TEST"
    
    echo "This test will verify your ability to:"
    echo "1. Restore critical files"
    echo "2. Rebuild system configurations"
    echo "3. Recover services"
    echo ""
    
    # Test 1: Backup accessibility
    echo "Test 1: Backup Accessibility"
    if [[ -d "$BACKUP_DIR" ]] && find "$BACKUP_DIR" -name "*.tar.gz" | grep -q .; then
        print_success "Backups are accessible"
    else
        print_error "No accessible backups found"
    fi
    echo ""
    
    # Test 2: Critical file location
    echo "Test 2: Critical Files Location"
    local critical_files=("/etc/hostname" "/etc/fstab" "/etc/passwd")
    for file in "${critical_files[@]}"; do
        if [[ -f "$file" ]]; then
            print_success "Found: $file"
        else
            print_warning "Missing: $file"
        fi
    done
    echo ""
    
    # Test 3: Service restart capability
    echo "Test 3: Service Restart Capability"
    echo "Key services that can be restarted:"
    systemctl list-units --type=service --state=running | head -5
}

# System hardening audit
audit_system_hardening() {
    print_header "SYSTEM HARDENING AUDIT"
    
    echo "Checking hardening measures..."
    echo ""
    
    # SSH hardening
    echo "SSH Configuration:"
    [[ $(grep -c "PermitRootLogin no" /etc/ssh/sshd_config) -gt 0 ]] && \
        print_success "Root login disabled" || \
        print_warning "Root login enabled"
    
    [[ $(grep -c "PasswordAuthentication no" /etc/ssh/sshd_config) -gt 0 ]] && \
        print_success "Password authentication disabled" || \
        print_warning "Password authentication enabled"
    echo ""
    
    # File permissions
    echo "File Permissions:"
    [[ $(stat -c %a /etc/passwd) == "644" ]] && \
        print_success "/etc/passwd: OK" || \
        print_warning "/etc/passwd: May need adjustment"
    
    [[ $(stat -c %a /etc/shadow) == "000" ]] || [[ $(stat -c %a /etc/shadow) == "640" ]] && \
        print_success "/etc/shadow: OK" || \
        print_warning "/etc/shadow: May need adjustment"
    echo ""
    
    # Firewall
    echo "Firewall Status:"
    if systemctl is-active --quiet firewalld || systemctl is-active --quiet ufw; then
        print_success "Firewall is active"
    else
        print_warning "Firewall may not be active"
    fi
    echo ""
    
    # SELinux/AppArmor
    echo "Mandatory Access Control:"
    if getenforce 2>/dev/null | grep -q -E "Enforcing|Permissive"; then
        print_success "SELinux is enabled"
    elif aa-status &>/dev/null; then
        print_success "AppArmor is enabled"
    else
        print_warning "No MAC system detected"
    fi
}

# Extended monitoring export utilities
export_metrics_to_file() {
    local format="${1:-json}"
    local output_file="$DATA_DIR/metrics_export_$(date +%Y%m%d_%H%M%S).$format"
    
    case "$format" in
        json)
            {
                echo "{"
                echo "  \"timestamp\": \"$(date -Iseconds)\","
                echo "  \"hostname\": \"$(hostname)\","
                echo "  \"cpu_usage\": $(get_cpu_usage),"
                echo "  \"memory_usage\": $(get_memory_usage),"
                echo "  \"uptime\": \"$(uptime -p 2>/dev/null || uptime)\""
                echo "}"
            } > "$output_file"
            ;;
        csv)
            {
                echo "timestamp,hostname,cpu_usage,memory_usage"
                echo "$(date -Iseconds),$(hostname),$(get_cpu_usage),$(get_memory_usage)"
            } > "$output_file"
            ;;
        *)
            log_error "Unsupported format: $format"
            return 1
            ;;
    esac
    
    log_info "Metrics exported to: $output_file"
    echo "$output_file"
}

# Extended system event logging
log_system_event() {
    local event_type="$1"
    local event_message="$2"
    local event_severity="${3:-INFO}"
    
    local event_log="$LOG_DIR/system_events_$(date +%Y%m%d).log"
    
    echo "[$(date +'%Y-%m-%d %H:%M:%S')] [$event_severity] [$event_type] $event_message" >> "$event_log"
}

