# Complete system health scoring
calculate_system_health_score() {
    local cpu_usage=$(get_cpu_usage)
    local mem_usage=$(get_memory_usage)
    local disk_usage=$(df / 2>/dev/null | tail -1 | awk '{print $5}' | tr -d '%')
    
    local cpu_score=$(( 100 - cpu_usage ))
    local mem_score=$(( 100 - mem_usage ))
    local disk_score=$(( 100 - disk_usage ))
    
    local total_score=$(( (cpu_score + mem_score + disk_score) / 3 ))
    
    echo "System Health Score: $total_score/100"
    echo ""
    echo "Component Scores:"
    echo "  CPU Health:    $cpu_score/100"
    echo "  Memory Health: $mem_score/100"
    echo "  Disk Health:   $disk_score/100"
    echo ""
    
    if (( total_score >= 80 )); then
        print_success "System health: EXCELLENT"
    elif (( total_score >= 60 )); then
        print_warning "System health: GOOD"
    else
        print_error "System health: NEEDS ATTENTION"
    fi
}

